ActiveRecord::Schema.define(version: 20261103000000) do
  create_table 'dummy_commit_loggables', force: true do |t|
    t.string(:name)
    t.integer(:role)
    t.timestamps(null: false)
  end

  create_table 'dummies', force: true do |t|
    t.string(:attribute_1)
    t.string(:attribute_2)
    t.datetime(:remote_updated_at, precision: 6) # same column generated by takamaru:shadow_version
    t.timestamps(null: false)
  end

  # Same table generated by takamaru:install
  create_table 'takamaru_commit_logs', force: true do |t|
    t.string(:exchange_name, null: false)
    t.uuid(:message_id, null: false, index: { unique: true })
    t.json(:payload, null: false)
    t.datetime(:published_at, index: true)
    t.integer(:attempts, null: false, default: 0)
    t.text(:last_error)
    t.timestamps(null: false)
    t.index(:id, where: 'published_at IS NULL', name: 'index_takamaru_commit_logs_pending')
  end
end
